guardrail.bad:
async fn slow_handler() -> String {
    std::thread::sleep(Duration::from_secs(1)); // BLOCKER: blocks runtime thread
    compute_something_heavy() // BLOCKER: starves other tasks
}

guardrail.good:
async fn slow_handler() -> String {
    tokio::time::sleep(Duration::from_secs(1)).await; // yields to runtime

    let result = tokio::task::spawn_blocking(|| compute_something_heavy()).await.unwrap();
    result
}

AppError::Database(err) => {
    tracing::error!("Database error: {:?}", err); // log internally
    (StatusCode::INTERNAL_SERVER_ERROR,
     Json(json!({"error": "Database error"}))).into_response() // sanitized client message
}

